test("掴める四角の上で右クリックすると、その下に描かれているノードの名前が外へ辿った順で 1 回だけ届く", () => {
  const { onOpenContextMenu } = rightClickHandleOver(() => drawn("panel"));

  expect(onOpenContextMenu).toHaveBeenCalledTimes(1);
  expect(onOpenContextMenu).toHaveBeenCalledWith(
    ["panel", "home"],
    HandleClickPoint,
  );
});

test("掴める四角の下が空き領域なら、名前は 1 つも届かず 1 回だけ届く", () => {
  const { onOpenContextMenu } = rightClickHandleOver(canvasSurface);

  expect(onOpenContextMenu).toHaveBeenCalledTimes(1);
  expect(onOpenContextMenu).toHaveBeenCalledWith([], HandleClickPoint);
});

test("掴める四角の上の右クリックも、ブラウザ既定のメニューを止める", () => {
  const { notCanceled } = rightClickHandleOver(() => drawn("panel"));

  expect(notCanceled).toBe(false);
});

test("掴める四角の下が artboard の枠の背景なら、その artboard の名前だけが届く", () => {
  const { onOpenContextMenu } = rightClickHandleOver(() =>
    screen.getByRole("button", { name: "home" }),
  );

  expect(onOpenContextMenu).toHaveBeenCalledWith(["home"], HandleClickPoint);
});

test("space を押しながら右ボタンで掴めるハンドルを押して引いても、中身は動かない", () => {
  // docs/06-ui.md「パン」
  const handle = setupRightHandle();
  holdSpace();

  dragFromHandle(handle, PointerButtons.Secondary);

  expect(canvasTransform()).toContain("translate(0px, 0px)");
});

test("space を押しながら右ボタンで土台を押して引いても、中身は動かない", () => {
  renderCanvas({ selection: setupSelection() });
  holdSpace();

  drag(
    canvasSurface(),
    { from: { x: 100, y: 100 }, to: { x: 130, y: 80 } },
    PointerButtons.Secondary,
  );

  expect(canvasTransform()).toContain("translate(0px, 0px)");
});

test("重ねた器（overlay）の中のものを飛ばし、器の外でいちばん手前の要素を返す", () => {
  const overlay = globalThis.document.createElement("div");
  const handle = globalThis.document.createElement("div");
  overlay.append(handle);
  const node = globalThis.document.createElement("div");
  const surface = globalThis.document.createElement("div");
  const at = { x: 10, y: 20 };
  stubElementsAt({ at, stack: [handle, overlay, node, surface] });

  const beneath = CanvasDom.elementBeneath(overlay, at);

  expect(Option.contains(beneath, node)).toBe(true);
});

test("その点で器の外に何も無ければ none を返す", () => {
  const overlay = globalThis.document.createElement("div");
  const handle = globalThis.document.createElement("div");
  overlay.append(handle);
  const at = { x: 10, y: 20 };
  stubElementsAt({ at, stack: [handle, overlay] });

  const beneath = CanvasDom.elementBeneath(overlay, at);

  expect(Option.isSome(beneath)).toBe(false);
});
